1	import { AppManager } from "../../../manager/AppManager.js";
2	import { aboutConfig } from "../scene/about.scene.js";
3	import { EnvSetup } from "../../../app/EnvSetup.js";
4	import type { IPageRuntime } from "../../../types/engine.types.js";
5	import { AboutProofRenderer } from "../render/AboutProofRenderer.js";
6	import { InfiniteGalleryRenderer } from "../render/InfiniteGalleryRenderer.js";
