11	export class AboutPageRuntime implements IPageRuntime {
12	  private _appManager: AppManager | null = null;
13	  private _proofRenderer: AboutProofRenderer | null = null;
14	  private _galleryRenderer: InfiniteGalleryRenderer | null = null;
15	
16	  async init(root?: ParentNode | null): Promise<void> {
17	    const three = aboutConfig.three;
18	    if (three) {
19	      const env = EnvSetup.shouldInit({
20	        canvasId: three.canvasId,
21	        root,
22	        allowedPageTypes: new Set(["about"]),
23	      });
24	      if (env.shouldInit) {
25	        this._appManager?.dispose();
26	        this._appManager = new AppManager();
27	        await this._appManager.run(aboutConfig, root);
28	      }
29	    }
30	
31	    const canvas = (root ?? document).querySelector<HTMLCanvasElement>(
32	      `#${PROOF_CANVAS_ID}`,
33	    );
34	    if (canvas instanceof HTMLCanvasElement) {
35	      this._proofRenderer?.dispose();
36	      this._proofRenderer = new AboutProofRenderer();
37	      await this._proofRenderer.init(canvas);
38	    }
39	
40	    const galleryCanvas = (root ?? document).querySelector<HTMLCanvasElement>(
41	      `#${GALLERY_CANVAS_ID}`,
42	    );
43	    if (galleryCanvas instanceof HTMLCanvasElement) {
44	      this._galleryRenderer?.dispose();
45	      this._galleryRenderer = new InfiniteGalleryRenderer();
46	      await this._galleryRenderer.init(galleryCanvas);
47	    }
48	  }
49	
50	  dispose(): void {
51	    this._appManager?.dispose();
52	    this._appManager = null;
53	    this._proofRenderer?.dispose();
54	    this._proofRenderer = null;
55	    this._galleryRenderer?.dispose();
56	    this._galleryRenderer = null;
57	  }
58	}
