1	import * as THREE from "three";
2	import { fetchWorksList } from "../../../api/getWork.js";
3	import type { WorkApiItem } from "../../../types/work.types.js";
4	
5	const CARD_HEIGHT = 1.8;
6	const CARD_WIDTH = CARD_HEIGHT * (16 / 9);
7	const ROTATION_SPEED_Y = 0.0005;
8	const MAX_IMAGES = 24;
9	const FALLBACK_COUNT = 8;
10	const FALLBACK_COLORS = [
11	  0x6644aa, 0x4488bb, 0x44aacc, 0x228866, 0x886622, 0xaa4466, 0x664488, 0x4466aa,
12	] as const;
13	
14	function computeRadius(cardCount: number): number {
15	  // ensure arc gap >= 15% of card width so cards never overlap
16	  const minArc = CARD_WIDTH * 1.15;
17	  return Math.max(10, (minArc * cardCount) / (2 * Math.PI));
18	}
19	
20	function loadTexture(
21	  loader: THREE.TextureLoader,
22	  url: string,
23	): Promise<THREE.Texture | null> {
24	  return new Promise((resolve) => {
25	    loader.load(
26	      url,
27	      (texture) => {
28	        texture.minFilter = THREE.LinearFilter;
29	        texture.generateMipmaps = false;
30	        resolve(texture);
31	      },
32	      undefined,
33	      () => resolve(null),
34	    );
35	  });
36	}
37	
38	function createCardMaterial(
39	  texture: THREE.Texture | null,
40	  color: number,
41	): THREE.MeshBasicMaterial {
42	  const mat = new THREE.MeshBasicMaterial({
43	    map: texture ?? null,
44	    color: texture ? 0xffffff : color,
45	    side: THREE.DoubleSide,
46	  });
47	
48	  if (texture) {
49	    // Flip UV.x on back face so back-side texture is not mirrored
50	    mat.onBeforeCompile = (shader) => {
51	      shader.fragmentShader = shader.fragmentShader.replace(
52	        "vec4 sampledDiffuseColor = texture2D( map, vMapUv );",
53	        `vec2 _uv = gl_FrontFacing ? vMapUv : vec2(1.0 - vMapUv.x, vMapUv.y);
54	        vec4 sampledDiffuseColor = texture2D( map, _uv );`,
55	      );
56	    };
57	    mat.needsUpdate = true;
58	  }
59	
60	  return mat;
61	}
