63	export class AboutProofRenderer {
64	  private _renderer: THREE.WebGLRenderer | null = null;
65	  private _scene: THREE.Scene | null = null;
66	  private _camera: THREE.PerspectiveCamera | null = null;
67	  private _group: THREE.Group | null = null;
68	  private _geometries: THREE.BufferGeometry[] = [];
69	  private _materials: THREE.Material[] = [];
70	  private _textures: THREE.Texture[] = [];
71	  private _rafId: number | null = null;
72	  private _resizeObserver: ResizeObserver | null = null;
73	  private _intersectionObserver: IntersectionObserver | null = null;
74	  private _rendering = false;
75	  private _disposed = false;
76	  private _canvas: HTMLCanvasElement | null = null;
77	
78	  async init(canvas: HTMLCanvasElement): Promise<void> {
79	    this._canvas = canvas;
80	
81	    const renderer = new THREE.WebGLRenderer({ canvas, antialias: true, alpha: true });
82	    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
83	    renderer.setClearAlpha(0);
84	    this._renderer = renderer;
85	
86	    const scene = new THREE.Scene();
87	    this._scene = scene;
88	
89	    const w = Math.max(canvas.clientWidth, 1);
90	    const h = Math.max(canvas.clientHeight, 1);
91	    // Frontal elevated view: ring curves left/right into depth
92	    const camera = new THREE.PerspectiveCamera(65, w / h, 0.1, 1000);
93	    camera.position.set(0, 3, 22);
94	    camera.lookAt(0, 0, 0);
95	    this._camera = camera;
96	
97	    scene.add(new THREE.AmbientLight(0xffffff, 1.0));
98	
99	    const group = new THREE.Group();
100	    this._group = group;
101	    scene.add(group);
102	
103	    let imageUrls: string[] = [];
104	    try {
105	      const response = await fetchWorksList(0, MAX_IMAGES, null);
106	      imageUrls = response.items
107	        .filter((item: WorkApiItem) => item.thumbnailImage.length > 0)
108	        .map((item: WorkApiItem) => item.thumbnailImage)
109	        .slice(0, MAX_IMAGES);
110	    } catch {
111	      // fallback to colored cards
112	    }
113	
114	    if (this._disposed) return;
115	
116	    if (imageUrls.length > 0) {
117	      const loader = new THREE.TextureLoader();
118	      const textures = await Promise.all(
119	        imageUrls.map((url) => loadTexture(loader, url)),
120	      );
121	      if (this._disposed) return;
122	      const radius = computeRadius(textures.length);
123	      textures.forEach((texture, i) => {
124	        if (texture) this._textures.push(texture);
125	        this._addCard(group, i, textures.length, texture, radius);
126	      });
127	    } else {
128	      const radius = computeRadius(FALLBACK_COUNT);
129	      for (let i = 0; i < FALLBACK_COUNT; i++) {
130	        this._addCard(group, i, FALLBACK_COUNT, null, radius);
131	      }
132	    }
133	
134	    this._syncSize();
135	    this._observeResize();
136	    this._observeVisibility();
137	  }
138	
139	  dispose(): void {
140	    this._disposed = true;
141	    this._stopRaf();
142	
143	    this._resizeObserver?.disconnect();
144	    this._resizeObserver = null;
145	
146	    this._intersectionObserver?.disconnect();
147	    this._intersectionObserver = null;
148	
149	    this._geometries.forEach((g) => g.dispose());
150	    this._geometries = [];
151	
152	    this._materials.forEach((m) => m.dispose());
153	    this._materials = [];
154	
155	    this._textures.forEach((t) => t.dispose());
156	    this._textures = [];
157	
158	    this._renderer?.dispose();
159	    this._renderer?.forceContextLoss();
160	    this._renderer = null;
161	    this._scene = null;
162	    this._camera = null;
163	    this._group = null;
164	    this._canvas = null;
165	  }
166	
167	  private _addCard(
168	    group: THREE.Group,
169	    index: number,
170	    total: number,
171	    texture: THREE.Texture | null,
172	    radius: number,
173	  ): void {
174	    const angle = (index / total) * Math.PI * 2;
175	    const x = radius * Math.cos(angle);
176	    const z = radius * Math.sin(angle);
177	
178	    const geo = new THREE.PlaneGeometry(CARD_WIDTH, CARD_HEIGHT);
179	    this._geometries.push(geo);
180	
181	    const mat = createCardMaterial(
182	      texture,
183	      FALLBACK_COLORS[index % FALLBACK_COLORS.length],
184	    );
185	    this._materials.push(mat);
186	
187	    const mesh = new THREE.Mesh(geo, mat);
188	    mesh.position.set(x, 0, z);
189	    // rotation.y so the front face (+Z normal) points radially outward from center
190	    mesh.rotation.y = Math.PI / 2 - angle;
191	    group.add(mesh);
192	  }
193	
194	  private readonly _tick = (): void => {
195	    if (this._disposed || !this._rendering) return;
196	    if (this._group) this._group.rotation.y += ROTATION_SPEED_Y;
197	    if (this._renderer && this._scene && this._camera) {
198	      this._renderer.render(this._scene, this._camera);
199	    }
200	    this._rafId = requestAnimationFrame(this._tick);
201	  };
202	
203	  private _startRaf(): void {
204	    if (this._rafId !== null || this._disposed) return;
205	    this._rendering = true;
206	    this._rafId = requestAnimationFrame(this._tick);
207	  }
208	
209	  private _stopRaf(): void {
210	    this._rendering = false;
211	    if (this._rafId !== null) {
212	      cancelAnimationFrame(this._rafId);
213	      this._rafId = null;
214	    }
215	  }
216	
217	  private _syncSize(): void {
218	    const canvas = this._canvas;
219	    const renderer = this._renderer;
220	    const camera = this._camera;
221	    if (!canvas || !renderer || !camera) return;
222	    const w = canvas.clientWidth;
223	    const h = canvas.clientHeight;
224	    if (w <= 0 || h <= 0) return;
225	    renderer.setSize(w, h, false);
226	    camera.aspect = w / h;
227	    camera.updateProjectionMatrix();
228	  }
229	
230	  private _observeResize(): void {
231	    if (!this._canvas) return;
232	    this._resizeObserver = new ResizeObserver(() => this._syncSize());
233	    this._resizeObserver.observe(this._canvas);
234	  }
235	
236	  private _observeVisibility(): void {
237	    if (!this._canvas) return;
238	    this._intersectionObserver = new IntersectionObserver(
239	      (entries) => {
240	        if (entries[0]?.isIntersecting) {
241	          this._startRaf();
242	        } else {
243	          this._stopRaf();
244	        }
245	      },
246	      { threshold: 0 },
247	    );
248	    this._intersectionObserver.observe(this._canvas);
249	  }
250	}
