41	const VERTEX_SHADER = /* glsl */ `
42	  uniform float scrollForce;
43	  uniform float time;
44	  uniform float isHovered;
45	  varying vec2 vUv;
46	  varying vec3 vNormal;
47	
48	  void main() {
49	    vUv = uv;
50	    vNormal = normal;
51	
52	    vec3 pos = position;
53	
54	    float curveIntensity = scrollForce * 0.3;
55	    float distanceFromCenter = length(pos.xy);
56	    float curve = distanceFromCenter * distanceFromCenter * curveIntensity;
57	
58	    float ripple1 = sin(pos.x * 2.0 + scrollForce * 3.0) * 0.02;
59	    float ripple2 = sin(pos.y * 2.5 + scrollForce * 2.0) * 0.015;
60	    float clothEffect = (ripple1 + ripple2) * abs(curveIntensity) * 2.0;
61	
62	    float flagWave = 0.0;
63	    if (isHovered > 0.5) {
64	      float wavePhase = pos.x * 3.0 + time * 8.0;
65	      float waveAmplitude = sin(wavePhase) * 0.1;
66	      float dampening = smoothstep(-0.5, 0.5, pos.x);
67	      flagWave = waveAmplitude * dampening;
68	      float secondaryWave = sin(pos.x * 5.0 + time * 12.0) * 0.03 * dampening;
69	      flagWave += secondaryWave;
70	    }
71	
72	    pos.z -= (curve + clothEffect + flagWave);
73	
74	    gl_Position = projectionMatrix * modelViewMatrix * vec4(pos, 1.0);
75	  }
76	`;
