78	const FRAGMENT_SHADER = /* glsl */ `
79	  uniform sampler2D map;
80	  uniform float opacity;
81	  uniform float blurAmount;
82	  uniform float scrollForce;
83	  varying vec2 vUv;
84	  varying vec3 vNormal;
85	
86	  void main() {
87	    vec4 color = texture2D(map, vUv);
88	
89	    if (blurAmount > 0.0) {
90	      vec2 texelSize = 1.0 / vec2(textureSize(map, 0));
91	      vec4 blurred = vec4(0.0);
92	      float total = 0.0;
93	
94	      for (float x = -2.0; x <= 2.0; x += 1.0) {
95	        for (float y = -2.0; y <= 2.0; y += 1.0) {
96	          vec2 offset = vec2(x, y) * texelSize * blurAmount;
97	          float weight = 1.0 / (1.0 + length(vec2(x, y)));
98	          blurred += texture2D(map, vUv + offset) * weight;
99	          total += weight;
100	        }
101	      }
102	      color = blurred / total;
103	    }
104	
105	    float curveHighlight = abs(scrollForce) * 0.05;
106	    color.rgb += vec3(curveHighlight * 0.1);
107	
108	    gl_FragColor = vec4(color.rgb, color.a * opacity);
109	  }
110	`;
