112	// ─── Helpers ────────────────────────────────────────────────────────────────
113	
114	function loadTexture(
115	  loader: THREE.TextureLoader,
116	  url: string,
117	): Promise<THREE.Texture | null> {
118	  return new Promise((resolve) => {
119	    loader.load(
120	      url,
121	      (texture) => {
122	        texture.minFilter = THREE.LinearFilter;
123	        texture.generateMipmaps = false;
124	        resolve(texture);
125	      },
126	      undefined,
127	      () => resolve(null),
128	    );
129	  });
130	}
131	
132	function computeOpacity(n: number): number {
133	  if (n < FADE_IN_START) return 0;
134	  if (n < FADE_IN_END) return (n - FADE_IN_START) / (FADE_IN_END - FADE_IN_START);
135	  if (n < FADE_OUT_START) return 1;
136	  if (n < FADE_OUT_END) return 1 - (n - FADE_OUT_START) / (FADE_OUT_END - FADE_OUT_START);
137	  return 0;
138	}
139	
140	function computeBlur(n: number): number {
141	  if (n < BLUR_IN_START) return MAX_BLUR;
142	  if (n < BLUR_IN_END) return MAX_BLUR * (1 - (n - BLUR_IN_START) / (BLUR_IN_END - BLUR_IN_START));
143	  if (n < BLUR_OUT_START) return 0;
144	  if (n < BLUR_OUT_END) return MAX_BLUR * ((n - BLUR_OUT_START) / (BLUR_OUT_END - BLUR_OUT_START));
145	  return MAX_BLUR;
146	}
