165	export class InfiniteGalleryRenderer {
166	  private _renderer: THREE.WebGLRenderer | null = null;
167	  private _scene: THREE.Scene | null = null;
168	  private _camera: THREE.PerspectiveCamera | null = null;
169	  private _clock: THREE.Clock | null = null;
170	  private _raycaster: THREE.Raycaster | null = null;
171	  private _canvas: HTMLCanvasElement | null = null;
172	
173	  private _planes: PlaneRecord[] = [];
174	  private _meshList: THREE.Object3D[] = [];
175	  private _textures: (THREE.Texture | null)[] = [];
176	  private _geometries: THREE.BufferGeometry[] = [];
177	  private _materials: THREE.ShaderMaterial[] = [];
178	
179	  private _rafId: number | null = null;
180	  private _rendering = false;
181	  private _disposed = false;
182	
183	  private _resizeObserver: ResizeObserver | null = null;
184	  private _intersectionObserver: IntersectionObserver | null = null;
185	
186	  private _scrollVelocity = 0;
187	  private _lastInteractionMs = 0;
188	  private _isAutoPlaying = false;
189	  private _autoPlayIntervalId: ReturnType<typeof setInterval> | null = null;
190	  private _hoveredIndex = -1;
191	  private _touchLastY = 0;
192	
193	  private readonly _pointerNDC = new THREE.Vector2();
194	
195	  private readonly _onWheel: (e: WheelEvent) => void;
196	  private readonly _onKeyDown: (e: KeyboardEvent) => void;
197	  private readonly _onTouchStart: (e: TouchEvent) => void;
198	  private readonly _onTouchMove: (e: TouchEvent) => void;
199	  private readonly _onPointerMove: (e: PointerEvent) => void;
200	  private readonly _onPointerLeave: (e: PointerEvent) => void;
201	
202	  constructor() {
203	    this._onWheel = (e) => {
204	      e.preventDefault();
205	      this._recordInteraction();
206	      this._scrollVelocity += e.deltaY * 0.01 * SCROLL_SPEED;
207	      this._scrollVelocity = Math.max(-MAX_SCROLL_VEL, Math.min(MAX_SCROLL_VEL, this._scrollVelocity));
208	    };
209	    this._onKeyDown = (e) => {
210	      if (e.key === "ArrowDown" || e.key === "ArrowRight") {
211	        this._recordInteraction();
212	        this._scrollVelocity += 2 * SCROLL_SPEED;
213	      } else if (e.key === "ArrowUp" || e.key === "ArrowLeft") {
214	        this._recordInteraction();
215	        this._scrollVelocity -= 2 * SCROLL_SPEED;
216	      }
217	    };
218	    this._onTouchStart = (e) => {
219	      if (e.touches[0]) this._touchLastY = e.touches[0].clientY;
220	      this._recordInteraction();
221	    };
222	    this._onTouchMove = (e) => {
223	      e.preventDefault();
224	      if (!e.touches[0]) return;
225	      const y = e.touches[0].clientY;
226	      const delta = this._touchLastY - y;
227	      this._touchLastY = y;
228	      this._recordInteraction();
229	      this._scrollVelocity += delta * 0.03 * SCROLL_SPEED;
230	      this._scrollVelocity = Math.max(-MAX_SCROLL_VEL, Math.min(MAX_SCROLL_VEL, this._scrollVelocity));
231	    };
232	    this._onPointerMove = (e) => {
233	      const canvas = this._canvas;
234	      const camera = this._camera;
